'use strict';
let projectUpdateFocus=null;
const publishedBriefNavigationOpen=new Map();
function publishedBriefNavigationKey(){return [state.auth?.account?.id||state.actor,state.project?.id,state.project?.version].join('|');}
function projectFlow(){return state.project_flow||{requests:[],tools:{links:{},mcp:{}},brief:{},can_request:false};}
function projectTask(id){return projectFlow().requests.find(r=>r.ref.id===id);}
function projectDomainLabel(){return typeof domainProfile==='function'&&domainProfile()?domainProfile().config.label:state.actor==='sam'?'Research':'Design';}
function projectTaskName(actor){return state.actors?.[actor]?.name||actor;}
// One collection over existing authorized records; opening it never creates or publishes a brief.
function domainBriefName(key){return (typeof domainKnowledgeProfile==='function'&&domainKnowledgeProfile(key)?.label)||({research:'Research',design:'Design'}[key])||key||'Domain';}
function domainBriefOutputAllowed(key,type){return !!state.domains?.profiles?.some(p=>p.key===key&&p.config.deliverable_types.includes(type));}
function domainBriefItems(){
 const items=[],business=state.intake?.published,shared=records('project-design-brief'),represented=new Set(),workItems=new Set(),domain=state.domains?.active;
 if(business?.body?.status==='published')items.push({key:'business|'+business.ref.id,title:'Business Intent',type:'Business sponsor',owner:records('project')[0]?.body.sponsor||'priya',status:'Published direction',action:'pflow-business-brief',id:business.ref.id+'|'+business.ref.revision});
 if(domainBriefOutputAllowed(domain,'Prototype design brief'))for(const plan of state.domain_objectives||[]){
  if(plan.body.owner!==state.actor||!plan.body.include_design_brief)continue;
  const work=plan.body.work_request?.id||'project';if(workItems.has(work))continue;workItems.add(work);
  const published=shared.find(r=>r.body.source_version?.id===plan.ref.id)||shared.find(r=>r.body.owner===plan.body.owner&&(r.body.work_request?.id||'project')===work);
  if(published)represented.add(published.ref.id);
  items.push({key:'plan|'+plan.ref.id,title:domainBriefName(domain)+' · Working brief',type:'Working brief',owner:plan.body.owner,status:plan.body.status==='completed'?'Completed privately':'Working draft',changed:!plan.current,action:'pflow-objectives-edit',id:plan.ref.id,shared:published});
 }
 for(const r of shared){
  const key=r.body.domain_key||'design';
  if(represented.has(r.ref.id)||!domainBriefOutputAllowed(key,'Prototype design brief'))continue;
  items.push({key:'published|'+r.ref.id,title:domainBriefName(key)+' · Working brief',type:'Working brief',owner:r.body.owner,status:'Shared v'+r.ref.revision,action:'pflow-shared-brief',id:r.ref.id+'|'+r.ref.revision});
 }
 if(domainBriefOutputAllowed('design','Evidence-backed developer brief')){
  const developers=state.developer_briefs||{private:[],shared:[]},privateIds=new Set();
  for(const r of developers.private||[]){
   if(r.body.owner!==state.actor)continue;
   privateIds.add(r.ref.id);const published=(developers.shared||[]).find(p=>p.body.source_version?.id===r.ref.id),last=r.last_shared||published?.ref;
   items.push({key:'developer|'+r.ref.id,title:r.body.title,type:'Developer brief',owner:r.body.owner,status:r.shared?'Shared v'+r.shared.revision+' · editable draft':last?'Draft changes since shared v'+last.revision:'Private draft',changed:r.changed?.length,action:'pflow-developer-draft',id:r.ref.id,shared:published});
  }
  for(const r of developers.shared||[]){if(privateIds.has(r.body.source_version?.id))continue;items.push({key:'developer-shared|'+r.ref.id,title:r.body.title,type:'Developer brief',owner:r.body.owner,status:'Shared v'+r.ref.revision+' · for review',changed:r.changed?.length,action:'devbrief-shared',id:label(r.ref)});}
 }
 return items;
}
function publishedDomainBriefItems(){
 const items=[],business=state.intake?.published;
 if(business?.body.status==='published')items.push({title:'Business Intent',type:'Business sponsor',owner:records('project')[0]?.body.sponsor||'priya',ref:business.ref,at:business.body.published_at,action:'pflow-business-brief',id:business.ref.id+'|'+business.ref.revision});
 for(const r of records('project-design-brief'))items.push({title:domainBriefName(r.body.domain_key||'design')+' · Working brief',type:r.body.domain||'Design',owner:r.body.owner,ref:r.ref,at:r.body.published_at,action:'pflow-shared-brief',id:r.ref.id+'|'+r.ref.revision});
 for(const r of state.developer_briefs?.shared||[])items.push({title:r.body.title||'Developer brief',type:'Developer brief',owner:r.body.owner,ref:r.ref,at:r.body.published_at,changed:r.changed?.length,action:'devbrief-shared',id:label(r.ref)});
 return items;
}
function domainBriefDirectory(showHeading=true){
 return `<section class="card accountability-panel domain-brief-directory workbench-created-surface" aria-label="Published working briefs">${showHeading?'<h2>Working briefs</h2>':''}${publishedDomainBriefItems().map(r=>`<article class="rule"><h3 class="acx-item-title"><a class="item-title-link workbench-document-link" href="#main" data-action="${r.action}" data-id="${esc(r.id)}">${esc(r.title)}</a></h3><p class="caption">${esc(r.type)} · ${esc(projectTaskName(r.owner))} · Published v${r.ref.revision}${r.at&&Number.isFinite(Date.parse(r.at))?' · '+esc(new Date(r.at).toLocaleDateString()):''}${r.changed?' · Linked context changed':''}</p></article>`).join('')||'<p>No published briefs.</p>'}</section>`;
}
function domainBriefNavigation(){return '<button type="button" class="app-navigation-link" data-action="pflow-business-intent" aria-haspopup="dialog"><span>Business Intent</span></button>';}
function openBusinessIntent(){
 const published=state.intake?.published;
 if(published?.body.status==='published')return openBusinessDomainBrief(published.ref.id+'|'+published.ref.revision);
 const intent=projectFlow().brief?.intent||records('intent')[0];
 modal('Business Intent',intent?`${para(intent.body.text)}<p class="caption">${esc(intent.body.status||'Shared direction')} · Version ${intent.ref.revision}</p>${sourceDetails([intent.ref])}`:'<p>No published Business Intent.</p>',null,null,{className:'settings-dialog domain-brief-dialog brief-reader'});
}
function currentWorkingDomainPlan(){
 const request=typeof chatThread==='function'?chatThread()?.body.work_request:null,task=request?projectTask(request.id):null;
 return projectObjectivePlan(task?.body.recipient===state.actor?task:null);
}
function workingDomainPlanStatus(plan=currentWorkingDomainPlan()){
 return !plan?'Set up the plan':!plan.current?'Review changed inputs':plan.body.status==='completed'?'Ready to guide work':plan.body.status==='working'?'Working plan':'Suggested plan';
}
function workingDomainBriefs(){
 if(!state.domains?.active)return '';
 const current=currentWorkingDomainPlan(),objectives=current?.body.objectives||current?.body.output?.objectives||[],otherPlans=domainBriefItems().filter(r=>r.action==='pflow-objectives-edit'&&r.id!==current?.ref.id);
 return `<section class="working-brief-current" aria-label="Private working brief"><p class="working-brief-edit"><a class="item-title-link" href="#main" data-action="pflow-brief">${current&&!current.current?'Review plan':'Edit plan'}</a><a class="item-title-link" href="#domain-chat-message" data-action="dchat-brief-coach">Discuss plan</a></p><p class="caption">Working plan for ${esc(projectDomainLabel())}. Revise as you learn.</p>${objectives.length?`<details class="working-brief-objectives"><summary>Objectives (${objectives.length})</summary><ol>${objectives.map(o=>`<li>${esc(o.title)}</li>`).join('')}</ol></details>`:''}${current?.body.include_design_brief?workingDomainPlanOutline(current):''}</section>${otherPlans.length?`<details class="domain-context-section"><summary>Other working plans</summary>${otherPlans.map(r=>`<p><a class="item-title-link workbench-document-link" href="#main" data-action="${r.action}" data-id="${esc(r.id)}">${esc(r.title)}</a><br><small>${esc(r.status)}</small></p>`).join('')}</details>`:''}`;
}
function briefPlanGroups(sections){
 const configured=typeof domainProfile==='function'?domainProfile()?.config?.brief_sections||[]:[],extras=new Set([...configured,...sections.map(s=>s.kind)]),indexed=sections.map((item,index)=>({item,index}));
 return [...(extras.has('hypotheses')?[['Business hypotheses','Assumptions to investigate, including evidence that could challenge them.',indexed.filter(({item})=>item.kind==='hypotheses')]]:[]),['Approach','Scope, tasks, outputs and dependencies.',indexed.filter(({item})=>!['requirement-implication','validation','hypotheses','discussion-guide'].includes(item.kind))],['Evaluation criteria','Quality criteria and supporting evidence.',indexed.filter(({item})=>item.kind==='validation')],...(extras.has('discussion-guide')?[['Draft discussion guide','Neutral questions to adapt around actual work and recent examples.',indexed.filter(({item})=>item.kind==='discussion-guide')]]:[])];
}
function workingDomainPlanOutline(plan){const sections=(plan.body.brief_sections||plan.body.output?.brief_sections||[]).filter(s=>s.kind!=='requirement-implication'&&s.disposition!=='omit');return `<div class="working-plan-outline">${briefPlanGroups(sections).map(([title,description,items])=>`<section><h4>${title}</h4>${items.length?items.map(({item})=>`<details><summary>${esc(item.title)}</summary>${para(item.text)}</details>`).join(''):'<p class="caption">Not defined</p>'}</section>`).join('')}</div>`;}

function downstreamDomainBriefs(){
 if(!state.domains?.active)return '';
 const drafts=domainBriefItems().filter(r=>r.action==='pflow-developer-draft'),canStart=domainBriefOutputAllowed(state.domains.active,'Evidence-backed developer brief')&&state.developer_briefs?.can_author&&!(state.developer_briefs.private||[]).some(r=>r.body.owner===state.actor&&r.body.conversation===(typeof chatThread==='function'?chatThread()?.ref.id:null));
 if(!drafts.length&&!canStart)return '';
 return `<details class="submission-downstream-briefs"><summary>Downstream handoff</summary><p class="caption">Prepare implementation guidance from the work, evidence and decisions.</p>${drafts.map(r=>`<p><a class="item-title-link workbench-document-link" href="#main" data-action="${r.action}" data-id="${esc(r.id)}">${esc(r.title)}</a><br><small>${esc(r.status)}</small></p>`).join('')}${canStart?'<p><a class="item-title-link" href="#main" data-action="devbrief-open">Start developer brief</a></p>':''}</details>`;
}
async function openDomainBriefDirectory(){return openBusinessIntent();}

function openBusinessDomainBrief(id){
 const published=[state.intake?.published,...(state.intake?.cases||[])].filter(r=>r?.body.status==='published'),r=published.find(r=>r.ref.id+'|'+r.ref.revision===id);
 if(!r)throw Error('This published business direction is unavailable. Reopen Business Intent.');
 const current=label(r.ref)===label(state.intake.published?.ref),earlier=published.filter((p,i,all)=>p.ref.id!==r.ref.id&&all.findIndex(v=>label(v.ref)===label(p.ref))===i);
 modal('Business Intent',`<p class="caption">${current?'Published direction':'Earlier published direction'} · ${esc(projectTaskName(records('project')[0]?.body.sponsor||'priya'))}</p><p class="caption">Publication establishes direction for investigation; it does not approve requirements or authorize development.</p><div class="brief-reader-content">${intakeSnapshot(r.body.snapshot)}<details><summary>Source version${earlier.length?' & publication history':''}</summary><p class="caption">${technicalRef(r.ref)} · Sponsor draft v${r.body.source_draft.revision}</p>${earlier.map(p=>`<p><a class="item-title-link" href="#main" data-action="pflow-business-brief" data-id="${esc(p.ref.id+'|'+p.ref.revision)}">${esc(p.body.snapshot.title)} · Version ${p.ref.revision}</a></p>`).join('')}</details></div>`,null,null,{className:'settings-dialog domain-brief-dialog brief-reader'});
}
async function openDomainDeveloperBrief(id){
 const r=(state.developer_briefs?.private||[]).find(r=>r.ref.id===id&&r.body.owner===state.actor);
 if(!r)throw Error('This private brief is unavailable. Open Prepare to share.');
 if(typeof saveWorkingReport==='function')await saveWorkingReport();
 selected=r.body.draft_id;view='contributions';await openDeveloperBrief();
}
function projectEntryStrip(){
 const tools=projectToolLinks();
 return `<div class="project-entry"><div class="chat-action-group" role="group" aria-label="Working brief"><span class="chat-action-label">Brief</span><div class="chat-action-buttons"><button type="button" class="quiet small" data-action="pflow-brief" aria-label="Working brief">Working brief</button></div></div>${tools?`<div class="chat-action-group" role="group" aria-label="Connected tools"><span class="chat-action-label">Tools</span><div class="chat-action-buttons">${tools}</div></div>`:''}<div class="chat-action-group chat-activity-group"><span class="chat-action-label">Activity</span>${projectUpdateFeed()}</div></div>`;
}
function projectToolLink(url,text){try{const u=new URL(url);return u.protocol==='https:'&&!u.username&&!u.password&&['figma.com','www.figma.com'].includes(u.hostname)?`<a class="project-tool-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(text)} ↗</a>`:'';}catch{return '';}}
function projectToolLinks(){if(state.domains?.active&&!['research','design'].includes(state.domains.active))return '';const links=projectFlow().tools.links;return state.actor==='sam'?projectToolLink(links.research_figjam,'Open FigJam'):state.actor==='lee'?projectToolLink(links.design_figma,'Open Figma')+projectToolLink(links.design_figjam,'Open FigJam'):'';}
function projectBrief(useAssignment=true){const task=useAssignment&&chatThread()?.body.work_request?projectTask(chatThread().body.work_request.id):null;return projectBriefModal('Working brief',projectObjectiveEntry(task),task);}
function projectRequestDetail(r){const b=r.body;projectBriefModal('Working brief',`${val('Task',b.title)}<p class="caption">${esc(projectTaskName(b.requested_by))} → ${esc(projectTaskName(b.recipient))}${b.recipient_domain?' · '+esc(domainKnowledgeProfile(b.recipient_domain)?.label||b.recipient_domain):''} · ${esc(b.status)}</p>${val('Objective',b.objective)}${val('Domain instructions',b.local_context||'No domain instructions.')}${val('Expected deliverable',b.expected_output)}${b.boundaries?val('Scope & constraints',b.boundaries):''}${r.published_outputs?.length?`<details><summary>Released responses (${r.published_outputs.length})</summary>${r.published_outputs.map(o=>`<p>${esc(o.title)} · Released for review</p>${o.packet?button('Inspect response packet','packet',packetKey(o.packet),'small'):''}`).join('')}</details>`:''}${r.changed.length?'<p class="banner signal-notice signal-advisory">The assignment context changed. Request a new assignment against current context before accepting it.</p>':''}<details><summary>Published evidence trail</summary>${b.packet_refs.map(p=>button('Inspect '+referenceText(p),'packet',packetKey(p),'small')+sourceDetails([p])).join('')}</details>${b.requirement_refs.length?`<section class="section"><h3>Domain requirements</h3>${b.requirement_refs.map(raw=>{const g=(b.requirement_guidance||[]).find(g=>label(g.ref)===label(raw)),original=records('requirement').find(r=>label(r.ref)===label(raw));return `<article class="rule"><strong>${esc(original?.body.title||'Requirement')}</strong>${original?val('Shared requirement',original.body.text):'<p class="caption">Historical requirement version; inspect the pinned packet.</p>'}${g?`${val('Local application',g.local_application)}${val('Expected evidence',g.expected_evidence)}`:''}<small>Version ${raw.revision} · Interpretation by ${esc(projectTaskName(b.requested_by))}; requirement authority unchanged.</small>${sourceDetails([raw])}</article>`;}).join('')}</section>`:''}${b.recipient===state.actor?projectObjectiveEntry(r):''}<div class="actions section">${b.recipient===state.actor&&b.status!=='cancelled'&&!r.changed.length?button(b.status==='requested'?'Accept & open work':'Open assigned work','pflow-request-start',r.ref.id,'primary'):''}${b.requested_by===state.actor&&b.status!=='cancelled'?button('Cancel work request','pflow-request-cancel',r.ref.id,'quiet'):''}</div>`,r);}
function projectRelevantIssues(work){const ids=new Set((work?.body.requirement_refs||[]).map(r=>r.id));return (state.bridge?.issues||[]).filter(r=>r.body.status!=='resolved'&&(r.body.requirement_refs.some(ref=>ids.has(ref.id))||(r.body.route==='intent'&&!r.body.requirement_refs.length)));}
function projectDependencies(work,compact=false){const issues=projectRelevantIssues(work),upstream=(work?.body.input_refs||[]).map(raw=>({pinned:raw,current:records('contribution').find(r=>r.ref.id===raw.id)})).filter(x=>x.current);return `${compact?'':projectUpdatePanel()}${upstream.length?`<details class="chat-context"><summary>${compact?'Upstream findings':'What upstream work means for you'} (${upstream.length})</summary>${upstream.map(({pinned,current:r})=>`<article class="rule"><strong>${esc(r.body.title)}</strong><small>Selected version ${pinned.revision}${pinned.revision!==r.ref.revision?' · Newer release available; adjust review scope':''}</small>${pinned.revision===r.ref.revision?`${para(r.body.observation)}${r.body.handoff?.downstream_needs?val('For your work',r.body.handoff.downstream_needs):''}${r.body.handoff?.open_questions?val('Still unresolved',r.body.handoff.open_questions):''}${r.body.limitation?val('Evidence limits',r.body.limitation):''}`:'<p class="caption">The selected historical release stays in the review basis. Inspect its packet before choosing a newer release.</p>'}${sourceDetails([pinned])}</article>`).join('')}</details>`:''}${issues.length?`<details class="chat-context project-pending" ${compact?'':'open'}><summary>${compact?'Team questions':'Pending cross-team questions'} (${issues.length})</summary>${compact?'':'<p class="caption">These are unresolved. Current requirements still apply; identify what depends on an answer.</p>'}${issues.slice(0,3).map(i=>`<article class="rule">${compact?`<h4><a class="item-title-link" href="#main" data-action="pflow-issue" data-id="${esc(i.ref.id)}">${esc(i.body.title)}</a></h4>`:`<strong>${esc(i.body.title)}</strong>`}<p>${esc(i.body.question)}</p><small>Next: ${esc(projectTaskName(i.body.next_owner))} · ${esc(i.body.status)}</small>${compact?'':button('Open question','pflow-issue',i.ref.id,'quiet small')}</article>`).join('')}${issues.length>3?button('See all open questions','pflow-bridge','','quiet small'):''}</details>`:''}${!compact&&state.domains?.active==='research'?'<details class="chat-context"><summary>What Design will receive</summary><p class="caption">Your published finding includes evidence limits, implications and open questions. Use Prepare to share to review the selected learning and exact packet before publication. Private conversation stays in Research.</p></details>':''}`;}
const projectToolLabels={research_figjam:'Research · FigJam board',design_figma:'Design · Figma file',design_figjam:'Design · FigJam board'};
function projectToolSettingsKeys(){return state.actor==='priya'?Object.keys(projectToolLabels):state.actor==='sam'?['research_figjam']:state.actor==='lee'?['design_figma','design_figjam']:[];}
function projectConfiguredTools(){const links=projectFlow().tools.links;return projectToolSettingsKeys().filter(k=>projectToolLink(links[k],projectToolLabels[k])).map(k=>({key:k,title:projectToolLabels[k],url:links[k]}));}
function projectConnectionShortcuts(){
 const tools=projectConfiguredTools(),definitions=state.coaching?.settings?.integrations?.items||[];
 const guidance=definitions.length?'Connection definitions are saved. Authorize selected-content imports in Settings → Integrations.':tools.length?'These shortcuts open your project files. Set up MCP connections in Settings → Integrations.':'No connections configured. Add MCP connections or Figma/FigJam file links in Settings → Integrations.';
 return `<details class="sponsor-source-tools" aria-label="Project connections"><summary>Project connections${tools.length?' · '+tools.length:''}</summary>${tools.map(t=>`<div class="sponsor-tool-row"><div><strong>${esc(t.title)}</strong><small>File link</small></div>${projectToolLink(t.url,'Open')}</div>`).join('')}<p class="caption">${guidance}</p>${button(tools.length?'Manage in Settings':'Open Settings','settings-integrations','','small')}</details>`;
}
function projectToolsSummary(){const configured=projectConfiguredTools();return `<section class="settings-connection"><div class="card-head"><h3>Figma & FigJam</h3>${tag(configured.length?'File links saved':'No file links',configured.length?'blue':'')}</div><p class="caption">Open the files your team works in. File links do not activate MCP access or import content.</p>${configured.map(t=>`<p>${projectToolLink(t.url,t.title)}</p>`).join('')}${projectToolSettingsKeys().length?button(configured.length?'Edit file links':'Add file links','pflow-tools','','small'):''}</section>`;}
function projectMcpSetup(){const mcp=projectFlow().tools.mcp;return `<details class="settings-detail"><summary>Figma MCP setup</summary>${tag('MCP client configuration','')}<p>Use this configuration in an approved MCP client. The Workbench import adapter needs its own user authorization; a file link or Codex connection does not supply it.</p><p>Remote server: <code>${esc(mcp.endpoint||'https://mcp.figma.com/mcp')}</code></p><label class="form-field"><span>Server configuration for an approved MCP client</span><textarea readonly rows="6">${esc(JSON.stringify(mcp.config||{},null,2))}</textarea></label><a href="https://developers.figma.com/docs/figma-mcp-server/remote-server-installation/" target="_blank" rel="noopener noreferrer">Figma connection requirements ↗</a><p class="caption">To review revised work here, export and upload it. Opening a linked file does not grant access or enable synchronization.</p></details>`;}
function projectToolsForm(){const tools=projectFlow().tools,own=projectToolSettingsKeys();modal('Figma & FigJam file links',`<p class="caption settings-scope">${esc(projectTitle())} · Settings → Integrations</p>${own.map(k=>`<label class="form-field"><span>${projectToolLabels[k]}</span><input name="${k}" type="url" maxlength="2000" value="${esc(tools.links[k]||'')}" placeholder="https://www.figma.com/${k.includes('figjam')?'board':'design'}/…"><small>Opens the selected file in a separate tab. Leave blank to remove.</small></label>`).join('')}<p class="caption">File links do not activate an MCP connection. MCP setup is in Settings → Integrations.</p>`,own.length?'Save file links':null,own.length?fd=>command('work-tools-save',{expected:tools.ref,links:Object.fromEntries(own.map(k=>[k,fd.get(k)]))}):null,{className:'settings-dialog'});}
async function projectFlowAction(action,id){if(!action.startsWith('pflow-'))return false;
 if(action==='pflow-updates-read'){for(const u of (state.domain_updates||[]).filter(u=>u.new))await command('project-update-open',{update:u.ref});await load();render();toast('All updates marked as read.');return true;}if(action==='pflow-update'){const update=(state.domain_updates||[]).find(u=>u.ref.id===id);await command('project-update-open',{update:update.ref});await load();projectUpdateFocus={...update,key:projectUpdateKey()};if(view==='contributions'){domainChatRail='requirements';if(typeof chatOpenBriefInputs==='function')chatOpenBriefInputs();render();}else projectUpdateDialog(update);}
 else if(action==='pflow-update-clear'){projectUpdateFocus=null;render();}
 else if(action==='pflow-update-target'){const u=(state.domain_updates||[]).find(u=>u.ref.id===id)||projectUpdateFocus;closeModal();if(u.target?.kind==='decision-rights'){await openDecisionRights();}else if(u.target?.kind==='review'){view='review';selected=u.target.id;render();}else if(u.target?.kind==='direction-review'){view='intent';intakeCaseId=u.target.id;intakeStep='review';render();}else if(u.target?.kind==='demo-delivery'){openDemoDeliveryReceipt(u.target.id);}else if(u.target?.kind==='issue'){view='review';selected=u.target.id;render();}else if(u.target?.kind==='requirement'){view='requirements';selected=u.target.id;render();}else if(u.target?.kind==='design-brief'){await projectOpenSharedBrief(u.target.ref);}else if(u.target?.kind==='packet'&&u.target.ref){inspectPacket(packetKey(u.target.ref));}else {view='decisions';selected=null;render();}}
 else if(action==='pflow-brief-refresh')await projectRefreshBriefInputs(id);
 else if(action==='pflow-brief-manual'){const task=id?projectTask(id):null;await command('domain-brief-create',{work_request:task?.ref||null});await load();projectObjectives(task);}
 else if(action==='pflow-brief-add')projectAppendBriefSection();
 else if(action==='pflow-objective-add')projectAppendObjective();
 else if(action==='pflow-brief-remove'||action==='pflow-objective-remove'){document.querySelector('[data-editor-key="'+id+'"]')?.remove();dirty=true;}
 else if(action==='pflow-shared-brief'){const [key,revision]=id.split('|');await projectOpenSharedBrief({id:key,revision:Number(revision)});}
 else if(action==='pflow-brief-for-work'){projectOpenWorkBrief(id);}
 else if(action==='pflow-design-brief')await projectDraftDesignBrief(id);
 else if(action==='pflow-objectives-view')projectObjectives(id?projectTask(id):null);
 else if(action==='pflow-objectives-open'){const task=chatThread()?.body.work_request?projectTask(chatThread().body.work_request.id):null;projectObjectives(task);}
 else if(action==='pflow-objectives'){if(!projectLeaveObjectiveEdits())return true;const r=id?projectTask(id):null;modal('Suggest '+projectDomainLabel().toLowerCase()+' objectives',`<p>The AI partner will use the shared business context, requirements, released findings${r?' and this working brief':''}.</p><p>Suggestions stay private and editable. This sends that context to the configured model.</p>`,'Suggest objectives',async()=>{const result=await command('domain-objectives-suggest',{work_request:r?.ref||null,consent:true});return {...result,domainObjectives:true,workRequest:r?.ref.id||null};},{busyLabel:'Preparing objectives…',refreshOnIdle:true});}
 else if(action==='pflow-objectives-edit')projectObjectiveEditor((state.domain_objectives||[]).find(r=>r.ref.id===id));
 else if(action==='pflow-brief-board'){bridgeBoard=id;render();}
 else if(action==='pflow-briefs')await openDomainBriefDirectory();
 else if(action==='pflow-business-intent')openBusinessIntent();
 else if(action==='pflow-business-brief')openBusinessDomainBrief(id);
 else if(action==='pflow-developer-draft')await openDomainDeveloperBrief(id);
 else if(action==='pflow-brief')projectBrief();
 else if(action==='pflow-requests')await openDomainBriefDirectory();
 else if(action==='pflow-request')projectRequestDetail(projectTask(id));
 else if(action==='pflow-request-start'){const r=projectTask(id);if(r.body.recipient_domain&&r.body.recipient_domain!==state.domains?.active){await command('domain-select',{domain:r.body.recipient_domain});await load();}const out=await command('work-request-start',{expected:r.ref});closeModal();await load();view='contributions';selected=out.id;render();}
 else if(action==='pflow-request-cancel'){const r=projectTask(id);modal('Cancel work request',settingField('note','Why is this work no longer requested?',''),'Cancel work request',fd=>command('work-request-respond',{expected:r.ref,action:'cancel',note:fd.get('note')}));}
 else if(action==='pflow-ask-sponsor'){bridgeBoard=state.domains?.active==='design'?'business-design':state.domains?.active==='research'?'business-research':'all-teams';bridgeRaiseForm({route:'coordination',kind:'question',owner:'priya'});}
 else if(action==='pflow-issue'){closeModal();view='review';selected=id;render();}
 else if(action==='pflow-bridge'){view='review';selected=null;bridgeSection='boards';render();}
 else if(action==='pflow-tools')projectToolsForm();
 return true;
}



function projectObjectivePlan(task=null){return (state.domain_objectives||[]).find(r=>task?r.body.work_request?.id===task.ref.id:!r.body.work_request);}
function projectBriefEditable(task=null){return ((typeof domainProfile==='function'&&domainProfile()?.config?.authors)||['sam','lee']).includes(state.actor)&&(!task||task.body.recipient===state.actor&&(!task.body.recipient_domain||task.body.recipient_domain===state.domains?.active));}
let projectBriefEditorTask=null;
function projectBriefModal(title,content,task=null){
 projectBriefEditorTask=task?.ref.id||null;
 const r=projectBriefEditable(task)?projectObjectivePlan(task):null,editable=r&&(r.editable??r.current);
 modal(title,`<p class="brief-descriptor">Incoming project requirements translated for your role, plus an editable work plan.</p>${content}`,editable?(r.body.include_design_brief?'Save working brief':'Save objectives'):null,editable?async fd=>{
  const objectives=r.body.objectives||r.body.output.objectives;
  const formKeys=fd.get('brief-editor-present')==='1',keys=formKeys?fd.getAll('objective-key'):objectives.map((o,i)=>String(i));
  const data={expected:r.ref,objectives:keys.map(key=>({...Object.fromEntries(['title','question','why','output','evidence'].map(k=>[k,fd.get(k+'-'+key)])),...(r.body.include_design_brief?{id:fd.get('objective-id-'+key)||objectives[Number(key)]?.id||'objective-'+key}:{})}))};
  if(r.body.include_design_brief){const sections=r.body.brief_sections||r.body.output.brief_sections,sectionKeys=formKeys?fd.getAll('brief-section-key'):sections.map((section,i)=>section.kind==='requirement-implication'?null:String(i)).filter(key=>key!==null);data.brief_sections=sectionKeys.map(key=>({...Object.fromEntries(['title','text','rationale','disposition','kind'].map(k=>[k,fd.get('brief-'+k+'-'+key)])),id:fd.get('brief-id-'+key)||sections[Number(key)]?.id||'section-'+key,requirement_ids:formKeys?fd.getAll('brief-reqs-'+key):[]}));data.complete=fd.get('brief-complete')==='on';}
  const result=await command('domain-objectives-save',data);
  return {...result,domainObjectives:true,workRequest:task?.ref.id||null};
 }:null,{className:'settings-dialog domain-brief-dialog',refreshOnIdle:true});
}
function projectObjectiveBasis(o,asFooter=false){
 const requirements=(o.requirement_ids||[]).map(id=>esc(get(id)?.body.title||'Requirement')),sources=o.basis_links||[],excerpts=sources.map(link=>`<blockquote>${esc(link.quote)}</blockquote><small>${technicalRef(link)}</small>`).join('');
 if(asFooter){if(!requirements.length&&!sources.length)return '';return `<footer class="brief-objective-footer" aria-label="Objective references">${requirements.length?`<p><span>Requirements:</span> ${requirements.join(' · ')}</p>`:''}${sources.length?`<details class="brief-objective-sources"><summary>Sources: ${[...new Map(sources.map(link=>[link.id+'|'+link.revision,link])).values()].map(link=>esc(referenceText(link,get(link.id)))).join(' · ')}</summary>${excerpts}</details>`:''}</footer>`;}
 return `<details class="brief-objective-basis"><summary>Requirement & source basis</summary>${requirements.map(title=>`<p>${title}</p>`).join('')}${excerpts}</details>`;
}
function projectObjectiveField(k,i,value,required=true){const labels={title:'Objective',question:'Question to investigate',why:'Why it matters',output:'Expected output',evidence:'Useful evidence'},limits={title:160,question:400,why:350,output:400,evidence:400},id='brief-objective-'+k+'-'+i;return `<label class="form-field" for="${id}"><span>${labels[k]}</span><textarea id="${id}" name="${k}-${i}" rows="${k==='title'?2:3}" maxlength="${limits[k]}" ${required?'required':''}>${esc(value)}</textarea></label>`;}
function projectObjectiveItem(o,key,r){return `<details class="brief-objective${r.refinement?.changes.some(c=>c.target.startsWith('objective:'+key+':'))?' is-brief-update':''}" data-editor-key="objective-${key}" ${key==='0'?'open':''}><summary>${esc(o.title||'New objective')}</summary><div class="details-body"><input type="hidden" name="objective-key" value="${esc(key)}"><input type="hidden" name="objective-id-${esc(key)}" value="${esc(o.id||'objective-'+key)}">${(r.editable??r.current)&&r.body.include_design_brief?`<div class="brief-objective-actions">${button('Remove objective','pflow-objective-remove','objective-'+key,'quiet small')}</div>`:''}${(r.editable??r.current)?['title','question','why','output','evidence'].map(k=>projectObjectiveField(k,key,o[k]||'',!r.body.include_design_brief)).join(''):`${val('Question to investigate',o.question)}${val('Why it matters',o.why)}${val('Expected output',o.output)}${val('Useful evidence',o.evidence)}`}${projectObjectiveBasis(o,true)}</div></details>`;}
function projectBriefCompletion(r){if(!r.body.include_design_brief)return '';const missing=r.readiness?.missing||[],complete=r.body.status==='completed'&&r.current;return `<section class="brief-completion" aria-label="Brief completeness"><h4>${complete?'Plan ready to guide work':'Work plan · draft'}</h4>${missing.length?`<p>Before this plan is ready to guide work:</p><ul>${missing.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p>Scope and objectives are filled. Review the plan before using it to guide the work.</p>'}${complete?'<p class="caption">Edits revise the working plan. Review the updated brief before sharing work based on it.</p>':''}${r.current?'<label class="checkbox"><input type="checkbox" name="brief-complete"><span>I have reviewed the brief and objectives. Use this plan to guide the work.</span></label>':''}</section>`;}
function projectObjectiveEntry(task=null){
 if(!projectBriefEditable(task))return '';
 const r=projectObjectivePlan(task),objectives=r&&(r.body.objectives||r.body.output.objectives);
 return `<section class="brief-objectives" aria-labelledby="brief-plan-title"><input type="hidden" name="brief-editor-present" value="1">${r?.refinement?`<details class="brief-update-receipt"><summary>Updated from discussion</summary>${para(r.refinement.summary)}${r.refinement.changes.map(c=>`<article><h4>${esc(c.label)}</h4>${val('From',c.before)}${val('To',c.after)}</article>`).join('')}</details>`:''}${r?.body.include_design_brief?projectDomainInterpretation(r):''}<section class="brief-editing-window" aria-label="Editable work plan"><header class="brief-editing-header"><h3 id="brief-plan-title">Work plan</h3><p class="caption">Edit objectives, approach and evaluation criteria.</p>${r?`<p class="caption">${r.current?'Current context':'Earlier incoming context · private edits are available'} · ${r.body.status==='completed'?'Ready to guide work':r.body.status==='working'?'Working plan':'Suggested plan'} · ${esc(r.body.mode)}</p>`:''}</header><section class="brief-objective-group" aria-labelledby="brief-objectives-title"><h4 id="brief-objectives-title">Objectives</h4><p class="caption">What this work should establish or validate.</p>${r?`<div id="brief-objective-list">${objectives.map((o,i)=>projectObjectiveItem(o,String(i),r)).join('')}</div>${(r.editable??r.current)&&r.body.include_design_brief?button('Add objective','pflow-objective-add','','quiet small'):''}`:'<p class="caption">No saved objectives. Draft from incoming context or start a blank brief.</p>'}</section>${r?.body.include_design_brief?projectDesignProposal(r):''}${r?.body.output.open_questions?.length?`<details class="brief-open-questions"><summary>Open questions</summary>${r.body.output.open_questions.map(q=>para(q)).join('')}</details>`:''}${r?projectBriefCompletion(r):''}</section>${projectBriefHistory(task,r)}<div class="workflow-card-actions">${r?.body.include_design_brief&&!r.current?button('Review changed inputs','pflow-brief-refresh',r.ref.id,'quiet small'):''}${button(r?.body.include_design_brief?'Draft revision':'Draft brief','pflow-design-brief',task?.ref.id||'','quiet small')}${!r?.body.include_design_brief?button('Start blank brief','pflow-brief-manual',task?.ref.id||'','quiet small'):''}</div></section>`;
}
function projectBriefHistory(task,current){const older=(state.domain_objectives||[]).filter(r=>r.ref.id!==current?.ref.id&&(task?r.body.work_request?.id===task.ref.id:!r.body.work_request));return older.length?`<details class="brief-proposal-history"><summary>Earlier proposals (${older.length})</summary><p class="caption">Retained, read only. A new proposal does not replace your working guidance until saved.</p>${older.map(r=>`<details><summary>Version ${r.ref.revision} · ${r.body.status==='working'?'Working guidance':'Proposal'}</summary>${sourceDetails([r.ref])}${(r.body.objectives||r.body.output.objectives).map(o=>`<article><h4>${esc(o.title)}</h4>${para(o.question)}${projectObjectiveBasis(o)}</article>`).join('')}${(r.body.brief_sections||r.body.output.brief_sections||[]).map(item=>`<article><h4>${esc(item.title)}</h4>${para(item.text)}<small>${esc(item.disposition||'proposed')}</small>${projectObjectiveBasis(item)}</article>`).join('')}</details>`).join('')}</details>`:'';}
const designBriefKinds={'hypotheses':'Business hypotheses','approach':'Approach','discussion-guide':'Discussion guide',purpose:'Purpose',scope:'Scope and exclusions','users-and-tasks':'Users and tasks','evidence-and-dependencies':'Evidence and dependencies', 'requirement-implication':'Requirement implication','design-consideration':'Additional consideration',validation:'Validation',deliverable:'Deliverable'};
function projectDesignInputs(inputs){
 if(!inputs)return '';
 return `<details class="brief-inputs"><summary>Upstream direction (${inputs.upstream.length})</summary><p class="caption">Published input, preserved as supplied. These are distinct from AI partner interpretations.</p>${inputs.research_count===0?'<p class="caption">No published Research findings are in this scope. Evidence needs remain open questions.</p>':''}${inputs.upstream.map(r=>`<article class="brief-source"><h4>${esc(r.title)}</h4><p class="caption">${esc(r.domain||r.kind.replaceAll('-',' '))}${r.author?' · '+esc(projectTaskName(r.author)):''} · Version ${r.ref.revision}</p>${sourceDetails([r.ref])}${r.fields.map(f=>`<strong>${esc(f.label)}</strong>${para(f.text)}${f.truncated?'<small>Excerpt shown; exact source version retained.</small>':''}`).join('')}</article>`).join('')}${inputs.additional_upstream?`<p class="caption">${inputs.additional_upstream} additional upstream records are in the preparation basis.</p>`:''}</details><details class="brief-inputs"><summary>Requirements to address (${inputs.requirements.length})</summary><p class="caption">Canonical wording and criteria. A proposed requirement still needs its governing decision.</p>${inputs.requirements.map(r=>`<article class="brief-source"><h4>${esc(r.title)}</h4><small>Version ${r.ref.revision} · ${esc(r.status)}</small>${sourceDetails([r.ref])}${para(r.text)}${val('Acceptance criteria',r.acceptance_criteria||'Not defined')}${r.conditions?val('Conditions',r.conditions):''}</article>`).join('')||'<p>No requirements in this brief’s scope.</p>'}</details>`;
}
function projectIncomingUserContext(r){const groups=r?.incoming_context||[];if(!groups.length)return '';return `<div class="brief-user-context">${groups.map(group=>`<section><h4>${esc(group.title)}</h4>${group.items.length?group.items.map(item=>para(item.text)).join(''):'<p class="caption">Not established in the incoming context.</p>'}</section>`).join('')}</div>`;}
function projectDomainInterpretation(r){
 const sections=(r?.body.brief_sections||r?.body.output?.brief_sections||[]).filter(s=>s.kind==='requirement-implication');
 return `<section class="brief-domain-interpretation" aria-label="Domain interpretation"><div class="brief-section-heading"><h3>Incoming context</h3><a class="item-title-link" href="#main" data-nav="requirements">Requirements</a></div><p class="caption">(Read only) User needs and requirements translated for your role.</p>${r&&!r.current?'<p class="caption">Inputs changed. This interpretation retains its earlier basis; review what changed before using it. Private work-plan edits remain available.</p>':''}${typeof needContextPlanLinks==='function'?needContextPlanLinks(r):''}${projectIncomingUserContext(r)}<div class="brief-role-considerations">${sections.map(item=>{const related=(item.requirement_ids||[]).map(id=>r?.body.design_inputs?.requirements?.find(req=>req.ref.id===id)?.title||get(id)?.body.title||'Requirement');return `<article class="brief-interpretation-item"><h4>${related.length?'Related requirement'+(related.length>1?'s':'')+': '+related.map(esc).join(' · '):esc(item.title)}</h4><p class="brief-interpretation-label">Implication for this work</p>${item.historical_interpretation?'<p class="caption">Earlier interpretation. Check evaluation criteria against current requirements.</p>':''}${para(item.text)}<details class="brief-reference-disclosure"><summary>View rationale</summary>${para(item.rationale)}${projectObjectiveBasis(item)}</details></article>`;}).join('')||'<p class="caption">No interpretation for this role yet.</p>'}</div><details class="brief-reference-disclosure brief-requirement-details"><summary>Source basis</summary>${(r?.incoming_context||[]).flatMap(g=>g.items).map(item=>`<p class="caption">${esc(item.origin)} · ${technicalRef(item.ref)} · ${esc(item.field)}</p>${para(item.text)}`).join('')}</details></section>`;
}
function projectDesignProposal(r){
 const sections=r.body.brief_sections||r.body.output.brief_sections||[],groups=briefPlanGroups(sections);
 return `<section class="design-brief-proposal" aria-label="Editable domain plan"><div id="brief-section-list">${groups.map(([heading,description,items])=>`<section class="brief-plan-group" data-plan-group="${heading==='Approach'?'approach':'evaluation'}"><h4>${heading}</h4><p class="caption">${description}</p>${items.map(({item,index})=>projectDesignSection(item,String(index),r.editable??r.current,r)).join('')||'<p class="caption">Not defined. Add a section or prepare a proposal.</p>'}</section>`).join('')}</div>${(r.editable??r.current)?button('Add plan detail','pflow-brief-add','','quiet small'):''}</section>`;
}
function projectDesignSection(item,key,current,plan){
 if(item.kind==='requirement-implication')return '';
 const fields=[['title','Section title',160,2],['text',item.kind==='validation'?'Evaluation criteria':item.kind==='discussion-guide'?'Draft interview questions':'Plan content',item.kind==='discussion-guide'?2400:800,item.kind==='discussion-guide'?10:4],['rationale','Why this matters',350,3]],choice=item.disposition||'proposed',manual=item.origin==='author';
 return `<details class="brief-proposal-item${!manual&&choice==='proposed'?' ac-suggestion-item':''}${plan?.refinement?.changes.some(c=>c.target.startsWith('section:'+key+':'))?' is-brief-update':''}" data-editor-key="section-${key}" ${key.startsWith('new-')?'open':''}><summary>${!manual&&choice==='proposed'?'<span class="ac-state ac-state-suggested">Suggested</span> ':''}${esc(item.title||'New brief section')} <small>${esc(designBriefKinds[item.kind])} · ${manual?'Author added':choice==='use'?'Use in brief':choice==='question'?'Needs discussion':choice==='omit'?'Not used':'Proposed'}</small></summary><div class="details-body">${current?`<div class="brief-objective-actions">${button('Remove section','pflow-brief-remove','section-'+key,'quiet small')}</div>`:''}${current?`<input type="hidden" name="brief-section-key" value="${esc(key)}"><input type="hidden" name="brief-id-${esc(key)}" value="${esc(item.id||'section-'+key)}">${manual?`<label class="form-field"><span>Section type</span><select name="brief-kind-${key}">${Object.entries(designBriefKinds).filter(([value])=>value!=='requirement-implication').map(([value,label])=>`<option value="${value}" ${value===item.kind?'selected':''}>${label}</option>`).join('')}</select></label><details><summary>Related requirements</summary>${(plan.body.design_inputs?.requirements||[]).map(req=>`<label class="checkbox"><input type="checkbox" name="brief-reqs-${key}" value="${esc(req.ref.id)}" ${(item.requirement_ids||[]).includes(req.ref.id)?'checked':''}><span>${esc(req.title)}</span></label>`).join('')}</details>`:`<input type="hidden" name="brief-kind-${key}" value="${esc(item.kind)}">`}${fields.map(([field,title,max,rows])=>{const id='brief-'+field+'-'+key;return `<label class="form-field" for="${id}"><span>${title}</span><textarea id="${id}" name="${id}" maxlength="${max}" rows="${rows}">${esc(item[field]||'')}</textarea></label>`;}).join('')}`:`${para(item.text)}${val('Rationale',item.rationale)}`}${current?`<label class="form-field" for="brief-disposition-${key}"><span>Use this section?</span><select id="brief-disposition-${key}" name="brief-disposition-${key}">${[['proposed','Review needed'],['use','Use in working brief'],['question','Needs discussion'],['omit','Leave out']].map(([value,title])=>`<option value="${value}" ${value===choice?'selected':''}>${title}</option>`).join('')}</select></label>`:''}${manual?'<p class="caption">Authored by you. Linked requirement excerpts remain separate from your interpretation.</p>':''}${projectObjectiveBasis(item,true)}</div></details>`;
}
function projectAppendBriefSection(){const task=projectBriefEditorTask?projectTask(projectBriefEditorTask):null,r=projectObjectivePlan(task),list=document.querySelector('#brief-section-list [data-plan-group="approach"]')||document.querySelector('#brief-section-list');if(!r||!list)return;const key='new-'+crypto.randomUUID(),item={id:key,origin:'author',kind:'design-consideration',title:'',text:'',rationale:'',disposition:'use',requirement_ids:[]};list.insertAdjacentHTML('beforeend',projectDesignSection(item,key,true,r));dirty=true;list.lastElementChild.scrollIntoView({block:'nearest'});}
function projectAppendObjective(){const list=document.querySelector('#brief-objective-list');if(!list)return;const key='new-'+crypto.randomUUID();list.insertAdjacentHTML('beforeend',projectObjectiveItem({id:key},key,{current:true,body:{include_design_brief:true}}));dirty=true;list.lastElementChild.open=true;list.lastElementChild.scrollIntoView({block:'nearest'});}
function projectOpenWorkBrief(id){const work=records('contribution-draft').find(r=>r.ref.id===id),task=work?.body.work_request?projectTask(work.body.work_request.id):null;return task?projectObjectives(task):projectBrief(false);}
function projectBriefGate(work){const info=domainInfo().brief_readiness?.[work?.ref.id];return info&&!info.ready?`<section class="brief-gate"><strong>Complete the Working brief before sharing</strong><ul>${info.missing.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${button('Open Working brief','pflow-brief-for-work',work.ref.id,'small')}</section>`:'';}
function projectSharedBriefBody(body){return `<div class="brief-reader-content"><section class="brief-reader-module"><h3>Working brief · planning basis</h3><p class="caption">Completed by ${esc(projectTaskName(body.completed_by))} · ${esc(body.completed_at)}</p>${body.changed_elements?.length?`<p><strong>Changed:</strong> ${body.changed_elements.map(esc).join(', ')}</p>`:''}</section>${(body.brief_sections||[]).map(item=>`<details class="brief-reader-module"><summary>${esc(item.title)} · ${item.kind==='requirement-implication'?(item.historical_interpretation?'Earlier interpretation · historical':'Domain interpretation · advisory'):item.disposition==='question'?'Needs discussion':'In brief'}</summary>${para(item.text)}${val('Rationale',item.rationale)}${projectObjectiveBasis(item)}</details>`).join('')}<details class="brief-reader-module"><summary>Design objectives (${body.objectives.length})</summary>${body.objectives.map(o=>`<article><h4>${esc(o.title)}</h4>${val('Question',o.question)}${val('Why',o.why)}${val('Expected output',o.output)}${val('Useful evidence',o.evidence)}${projectObjectiveBasis(o)}</article>`).join('')}</details></div>`;}
async function projectOpenSharedBrief(ref){const r=await command('domain-brief-read',{ref});modal('Shared Working brief',`<p class="caption">Working brief · Version ${r.ref.revision} · Exact shared version</p>${sourceDetails([r.ref])}<div class="brief-reader-content">${projectSharedBriefBody(r.body)}${r.previous?`<details><summary>Previous shared version · v${r.previous.ref.revision}</summary>${sourceDetails([r.previous.ref])}${projectSharedBriefBody(r.previous.body)}</details>`:''}</div>`,null,null,{className:'settings-dialog domain-brief-dialog brief-reader'});}
async function projectDraftDesignBrief(id){
 if(busy||!projectLeaveObjectiveEdits())return;
 const task=id?projectTask(id):null,session=projectUpdateKey()+'|'+state.domains?.active;busy=true;
 try{
  const preview=await command('domain-brief-preview',{work_request:task?.ref||null});
  if(session!==projectUpdateKey()+'|'+state.domains?.active)throw Error('The workbench changed. Open the brief again.');
  modal('Draft Working brief',`<p>${'Prepare '+((typeof domainProfile==='function'?domainProfile()?.config?.brief_sections:[])?.includes('discussion-guide')?'hypotheses, approach and a draft discussion guide':'objectives, approach and evaluation criteria')+' from accepted project inputs and domain guidance.'}</p>${projectDesignInputs(preview.inputs)}<details><summary>All input versions (${preview.basis.length})</summary>${preview.basis.map(r=>`<p class="caption">${technicalRef(r)}</p>`).join('')}</details>${preview.additional_pending_questions?`<p class="caption">${preview.additional_pending_questions} additional pending questions are outside this bounded preparation.</p>`:''}<p class="caption">These displayed input versions and configured domain guidance will be sent to the AI partner. Earlier saved proposals remain retained; a new proposal is private until you choose what to use.</p>`,'Draft brief',async()=>{const out=await command('domain-objectives-suggest',{work_request:task?.ref||null,include_brief:true,expected_signature:preview.signature,consent:true});return {...out,domainObjectives:true,workRequest:task?.ref.id||null};},{className:'settings-dialog domain-brief-dialog',busyLabel:'Drafting brief…',refreshOnIdle:true});
 }finally{busy=false;}
}
function projectObjectives(task=null){return projectBriefModal('Working brief',projectObjectiveEntry(task),task);}
function projectObjectiveEditor(r){return projectObjectives(r.body.work_request?projectTask(r.body.work_request.id):null);}
function projectLeaveObjectiveEdits(action){if(['pflow-brief-add','pflow-objective-add','pflow-brief-remove','pflow-objective-remove'].includes(action))return true;const dialog=document.querySelector('#modal');if(dialog?.open&&dialog.querySelector('.brief-objectives')&&typeof dirty!=='undefined'&&dirty){closeModal();return !dialog.open;}return true;}


function projectUpdateFeed(){const updates=state.domain_updates||[],fresh=updates.filter(u=>u.new);return `<details class="project-update-feed"><summary>Updates${fresh.length?' · '+fresh.length+' new':''}</summary><div class="project-update-items">${fresh.length>1?button('Mark all read','pflow-updates-read','','compact-text-action'):''}${updates.slice(0,6).map(u=>`<button class="quiet small" data-action="pflow-update" data-id="${esc(u.ref.id)}">${u.new?'<span class="update-dot" aria-label="New">●</span> ':''}${esc(u.title)}</button>`).join('')||'<p class="caption">Recorded decisions and published findings will appear here.</p>'}${updates.length>6?`<details><summary>Earlier updates</summary>${updates.slice(6).map(u=>button(u.title,'pflow-update',u.ref.id,'quiet small')).join('')}</details>`:''}</div></details>`;}
function projectUpdatePanel(){const u=projectUpdateFocus;if(!u||u.key!==projectUpdateKey())return '';return `<section class="project-update-focus"><strong>Update to review</strong><h3>${esc(u.title)}</h3><p>${esc(u.detail)}</p><p class="caption">Related requirements are highlighted where they are in scope. Your selected review scope has not changed.</p>${button('Inspect full record','pflow-update-target',u.ref.id,'quiet small')}${button('Clear highlight','pflow-update-clear','','quiet small')}</section>`;}
function projectRequirementUpdated(id){return projectUpdateFocus?.key===projectUpdateKey()&&projectUpdateFocus.requirement_refs.some(r=>r.id===id);}
function projectUpdateDialog(u){modal('Project update',`${val('Recorded update',u.title)}${para(u.detail)}<p class="caption">${esc(u.boundary)}</p>${button('Inspect full record','pflow-update-target',u.ref.id,'small')}`,null,null,{className:'settings-dialog'});}

function projectUpdateKey(){return [state.project.id,state.project.version,state.auth?.account?.id||'development',state.actor].join('|');}

document.addEventListener('toggle',e=>{if(e.target.isConnected!==false&&e.target.hasAttribute?.('data-published-briefs'))publishedBriefNavigationOpen.set(publishedBriefNavigationKey(),e.target.open);},true);

async function projectRefreshBriefInputs(id){
 if(busy||!projectLeaveObjectiveEdits())return;
 const plan=(state.domain_objectives||[]).find(r=>r.ref.id===id);if(!plan)return;
 const session=projectUpdateKey()+'|'+state.domains?.active;busy=true;
 try{
  const preview=await command('domain-brief-refresh-preview',{expected:plan.ref});
  if(session!==projectUpdateKey()+'|'+state.domains?.active)throw Error('The workbench changed. Open the brief again.');
  modal('Review changed inputs',`<p>Keep your saved objectives and plan while bringing in the current shared inputs. Earlier interpretations remain labelled as historical. Review your evaluation criteria before marking the plan ready.</p><p>No model call or publication occurs here.</p><details open><summary>Changed inputs (${preview.changes.length})</summary>${preview.changes.map(c=>`<article><h4>${esc(c.title)}</h4><p class="caption">${c.before?'Version '+c.before.revision:'New input'} → ${c.after?'Version '+c.after.revision:'No longer in the current scope'}</p>${sourceDetails([c.before,c.after].filter(Boolean))}</article>`).join('')||'<p>Domain guidance or the context view changed; review the current inputs below.</p>'}</details>${projectDesignInputs(preview.inputs)}${preview.additional_pending_questions?`<p class="caption">${preview.additional_pending_questions} other pending questions remain outside this preparation.</p>`:''}`,'Refresh inputs',async()=>{
   const out=await command('domain-brief-refresh',{expected:preview.expected,expected_signature:preview.signature,confirm:true});
   return {...out,domainObjectives:true,workRequest:plan.body.work_request?.id||null};
  },{className:'settings-dialog domain-brief-dialog',refreshOnIdle:true});
 }finally{busy=false;}
}
